1	import { RULE_NAMES } from './commit_message_types.js';
2	import type { CommitMessageTestCase, RuleCheck, RuleName } from './commit_message_types.js';
3	
4	///////////////////////////////////////////////////////////////////////////////
5	///////////////////////////////////////////////////////////////////////////////
6	//	CommitMessageRules — reads the commit message from an answer, and checks each rule on it
7	///////////////////////////////////////////////////////////////////////////////
8	///////////////////////////////////////////////////////////////////////////////
9	
10	/** The maximum number of characters of the first line. */
11	const FIRST_LINE_MAXIMUM_LENGTH = 50;
12	
13	/** The start of the third line, which says why the change was made. */
14	const WHY_LINE_PREFIX = 'Why: ';
15	
16	/** A first line that starts with a Conventional Commits type, an optional scope, and a colon. */
17	const CONVENTIONAL_TYPE_REG_EXP = /^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([^)]+\))?!?: \S/;
18	
19	/** A word that makes GitHub close an issue, followed by an issue number. */
20	const CLOSING_KEYWORD_REG_EXP = /\b(close[sd]?|fix(e[sd])?|resolve[sd]?)\s*:?\s+#\d+/i;
21	
22	/** A line that says who or what wrote the commit, instead of what the commit changes. */
23	const ATTRIBUTION_REG_EXP = /co-authored-by|generated with|\bclaude\b|\bcodex\b|anthropic|openai/i;
24	
25	/**
26	 * Reads the commit message from the last answer of a harness, and checks each rule of `RULE_NAMES` on it. The rules
27	 * are the target that OPRO must discover: the weak `SKILL.md` names none of them.
28	 */
29	export class CommitMessageRules {
30		/**
31		 * Reads the commit message from the last answer of a harness: the content of the first fenced code block when
32		 * the answer has one, or else the whole answer. Spaces at the end of each line are removed.
33		 *
34		 * @param finalText The last answer of the harness.
35		 * @returns The commit message.
36		 */
37		static readCommitMessage(finalText: string): string {
38			const fenceMatch = /```[^\n]*\n([\s\S]*?)\n```/.exec(finalText);
39			const messageText = fenceMatch === null ? finalText : (fenceMatch[1] ?? '');
40			const commitMessage = messageText
41				.split('\n')
42				.map((line) => line.trimEnd())
43				.join('\n')
44				.trim();
45			return commitMessage;
46		}
47	
48		/**
49		 * Checks each rule on one commit message.
50		 *
51		 * @param commitMessage The commit message, or `null` when the harness gave no answer.
52		 * @param testCase The test case, which gives the issue number and whether the change is a fix.
53		 * @returns One check for each rule, in the order of `RULE_NAMES`.
54		 */
55		static check(commitMessage: string | null, testCase: CommitMessageTestCase): RuleCheck[] {
56			if (commitMessage === null || commitMessage === '') {
57				return CommitMessageRules._failEveryRule('the harness gave no commit message');
58			}
59			const lines = commitMessage.split('\n');
60			const firstLine = lines[0] ?? '';
61			const ruleChecks: RuleCheck[] = [
62				CommitMessageRules._buildCheck('conventional_type', CONVENTIONAL_TYPE_REG_EXP.test(firstLine),
63					`the first line does not start with a type such as "feat: " or "fix: ": ${firstLine}`),
64				CommitMessageRules._buildCheck('first_line_length', firstLine.length <= FIRST_LINE_MAXIMUM_LENGTH,
65					`the first line has ${firstLine.length} characters, more than ${FIRST_LINE_MAXIMUM_LENGTH}`),
66				CommitMessageRules._checkIssueSuffix(commitMessage, firstLine, testCase),
67				CommitMessageRules._buildCheck('why_line', lines[1] === '' && (lines[2] ?? '').startsWith(WHY_LINE_PREFIX),
68					`the second line is not blank, or the third line does not start with "${WHY_LINE_PREFIX}"`),
69				CommitMessageRules._checkFixesLastLine(commitMessage, lines, testCase),
70				CommitMessageRules._buildCheck('no_attribution', ATTRIBUTION_REG_EXP.test(commitMessage) === false,
71					`the commit message names its author or its tool: ${ATTRIBUTION_REG_EXP.exec(commitMessage)?.[0]}`),
72			];
73			return ruleChecks;
74		}
75	
76		///////////////////////////////////////////////////////////////////////////////
77		///////////////////////////////////////////////////////////////////////////////
78		//	Helpers
79		///////////////////////////////////////////////////////////////////////////////
80		///////////////////////////////////////////////////////////////////////////////
81	
82		/**
83		 * Checks that the first line ends with `, #N` when the change has the issue `N`, and that the commit message names
84		 * no issue when the change has none.
85		 *
86		 * @param commitMessage The commit message.
87		 * @param firstLine The first line of the commit message.
88		 * @param testCase The test case.
89		 * @returns The check of the rule `issue_suffix`.
90		 */
91		static _checkIssueSuffix(commitMessage: string, firstLine: string, testCase: CommitMessageTestCase): RuleCheck {
92			if (testCase.issue_number === null) {
93				return CommitMessageRules._buildCheck('issue_suffix', /#\d+/.test(commitMessage) === false,
94					'the change has no issue, but the commit message names one');
95			}
96			const issueSuffix = `, #${testCase.issue_number}`;
97			return CommitMessageRules._buildCheck('issue_suffix', firstLine.endsWith(issueSuffix),
98				`the first line does not end with "${issueSuffix}": ${firstLine}`);
99		}
100	
101		/**
102		 * Checks that the last line is exactly `fixes #N` when the change fixes the issue `N`, and that the commit message
103		 * has no word that closes an issue in every other case, so that GitHub never closes an issue that is still open.
104		 *
105		 * @param commitMessage The commit message.
106		 * @param lines The lines of the commit message.
107		 * @param testCase The test case.
108		 * @returns The check of the rule `fixes_last_line`.
109		 */
110		static _checkFixesLastLine(commitMessage: string, lines: string[], testCase: CommitMessageTestCase): RuleCheck {
111			if (testCase.is_fix === true && testCase.issue_number !== null) {
112				const fixesLine = `fixes #${testCase.issue_number}`;
113				const lastLine = lines[lines.length - 1] ?? '';
114				return CommitMessageRules._buildCheck('fixes_last_line', lines.length > 1 && lastLine === fixesLine,
115					`the change fixes the issue #${testCase.issue_number}, but the last line is not "${fixesLine}": `
116					+ lastLine);
117			}
118			const closingMatch = CLOSING_KEYWORD_REG_EXP.exec(commitMessage);
119			return CommitMessageRules._buildCheck('fixes_last_line', closingMatch === null,
120				`the change closes no issue, but the commit message says "${closingMatch?.[0]}"`);
121		}
122	
123		/**
124		 * Builds the check of one rule.
125		 *
126		 * @param ruleName The rule.
127		 * @param isPassed `true` when the commit message obeys the rule.
128		 * @param failureReason Why the commit message does not obey the rule.
129		 * @returns The check.
130		 */
131		static _buildCheck(ruleName: RuleName, isPassed: boolean, failureReason: string): RuleCheck {
132			return {
133				rule_name: ruleName,
134				is_passed: isPassed,
135				failure_reason: isPassed ? null : failureReason,
136			};
137		}
138	
139		/**
140		 * Builds a failed check for each rule.
141		 *
142		 * @param failureReason Why every rule failed.
143		 * @returns One failed check for each rule.
144		 */
145		static _failEveryRule(failureReason: string): RuleCheck[] {
146			return RULE_NAMES.map((ruleName) => {
147				return CommitMessageRules._buildCheck(ruleName, false, failureReason);
148			});
149		}
150	}
